contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Simulate a curated pool calling mintSynth(pool mints synthetic to member)
    // params: pool address (must be a curated pool per DAO, but we can't require that here), member to receive minted synth, amount to mint
    function run(address pool, address member, uint256 amount) public payable {
        require(pool != address(0) && member != address(0));

        // read debt and balance before call (public getters)
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);
        uint256 beforeBalance = c.getmapAddress_LPBalance(pool);
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 memberBalBefore = c.balanceOf(member);

        bool reverted = false;
        uint256 mintedReturned = 0;
        // call as if pool (msg.sender will be this contract). The contract creating c is different in checker
        // We must call c.mintSynth which is external and restricted by onlyPool; if pool is not curated, it should revert.
        // Wrap in try/catch to capture revert
        try c.mintSynth(member, amount) returns (uint256 r) {
            mintedReturned = r;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 afterDebt = c.getmapAddress_LPDebt(pool);
        uint256 afterBalance = c.getmapAddress_LPBalance(pool);
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 memberBalAfter = c.balanceOf(member);

        // General property: if call succeeded then:
        //  - totalSupply increased by exactly mintedReturned (minted amount)
        //  - member's balance increased by exactly mintedReturned
        //  - pool's recorded LP debt increased by exactly mintedReturned
        // If the call reverted, none of these on-chain observable values should have changed.
        assert(
            reverted
            ? (
                afterDebt == beforeDebt
                && afterBalance == beforeBalance
                && totalSupplyAfter == totalSupplyBefore
                && memberBalAfter == memberBalBefore
              )
            : (
                // when not reverted: mintedReturned equals the observed deltas
                mintedReturned == (afterDebt - beforeDebt)
                && mintedReturned == (totalSupplyAfter - totalSupplyBefore)
                && mintedReturned == (memberBalAfter - memberBalBefore)
              )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We simulate a curated Pool calling burnSynth on C. The caller will be this contract.
    // Parameters are the pool address (passed as 'pool') which in real usage must be a curated pool,
    // but here we accept any address; if the call reverts then observable state must be unchanged.
    function run(address pool) public payable {
        require(pool != address(0));

        // Observe pre-call public state
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforePoolLPBalance = c.getmapAddress_LPBalance(pool);
        uint256 beforePoolLPDebt = c.getmapAddress_LPDebt(pool);
        uint256 beforeThisSynthBalance = c.balanceOf(address(this));

        bool reverted;
        try c.burnSynth() returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call public state
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterPoolLPBalance = c.getmapAddress_LPBalance(pool);
        uint256 afterPoolLPDebt = c.getmapAddress_LPDebt(pool);
        uint256 afterThisSynthBalance = c.balanceOf(address(this));

        // If the call reverted, none of the observed on-chain values should have changed.
        // If it succeeded, then:
        //  - the contract's synthetic balance decreased by exactly the amount burned (deltaSynth)
        //  - the pool's recorded LP debt decreased by exactly that burned synthetic amount
        //  - totalSupply decreased by exactly that burned synthetic amount
        //  - the pool's recorded LP balance decreased by some non-negative amount (handled inside C), and
        //    it must not increase as a result of burnSynth

        // Compute deltas safely using comparisons rather than subtraction that could underflow in assert
        bool noChange = (
            afterTotalSupply == beforeTotalSupply &&
            afterPoolLPBalance == beforePoolLPBalance &&
            afterPoolLPDebt == beforePoolLPDebt &&
            afterThisSynthBalance == beforeThisSynthBalance
        );

        // When successful, the burned amount equals the before-after of C's synth balance
        bool successConsistency = false;
        if (!reverted) {
            // burned = beforeThisSynthBalance - afterThisSynthBalance
            if (beforeThisSynthBalance >= afterThisSynthBalance) {
                uint256 burned = beforeThisSynthBalance - afterThisSynthBalance;
                // require that totalSupply decreased by burned
                bool totalSupplyOk = (beforeTotalSupply >= afterTotalSupply) && (beforeTotalSupply - afterTotalSupply == burned);
                // require that pool debt decreased by burned
                bool debtOk = (beforePoolLPDebt >= afterPoolLPDebt) && (beforePoolLPDebt - afterPoolLPDebt == burned);
                // require that pool LP balance did not increase
                bool lpBalanceNonIncrease = (afterPoolLPBalance <= beforePoolLPBalance);
                successConsistency = totalSupplyOk && debtOk && lpBalanceNonIncrease;
            } else {
                successConsistency = false;
            }
        }

        assert(reverted ? noChange : successConsistency);
    }

    receive() external payable {}
}

