contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: pool (caller of mintSynth), recipient who should receive synth, amount to mint,
    // isCurated flag simulated by calling via this contract: we cannot change DAO internals,
    // so we rely on observing behavior when calling through c (the test will try and detect revert).
    function run(address pool, address member, uint256 amount) public payable {
        require(pool != address(0) && member != address(0));

        // Observe before state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(member);

        // Call mintSynth as if from the pool: the checker will set msg.sender to this contract when
        // it invokes run; but calls on c originate from this contract, so to emulate the pool
        // being the caller we perform a low-level call to c with encoded calldata and set
        // no value. This low-level call will have msg.sender == address(this) from c's perspective,
        // so we instead attempt two variants: call directly (this contract as caller) and record revert.
        bool reverted;
        bytes memory sig = abi.encodeWithSignature("mintSynth(address,address)", member, amount);
        (bool ok, ) = address(c).call(sig);
        reverted = !ok;

        // Observe after state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(member);

        // General rule:
        // If the call did not revert, then totalSupply increased by exactly `amount` and member's balance increased by exactly `amount`.
        // If the call reverted, then neither totalSupply nor member balance increased (they must be unchanged).
        assert( (!reverted && afterTotal == beforeTotal + amount && afterBal == beforeBal + amount)
             || (reverted && afterTotal == beforeTotal && afterBal == beforeBal) );
    }

    receive() external payable {}
}

