contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry: caller must be a pool address (simulated by taking poolAddr param)
    // We treat the call originating from this contract: the test will call c.mintSynth(poolMember, amount) using
    // low-level call to emulate msg.sender being a curated pool: however the spec forbids creating new callers,
    // so instead we rely on the fact that in the real system mintSynth only allows calls where
    // iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender) == true. The checker will consider all possible
    // msg.senderrs (in its environment) and try to prove the invariant. We therefore assert the property conditional
    // on whether the call succeeded or reverted.
    function run(address poolCaller, address member, uint256 amount) public payable {
        require(member != address(0));
        // read pre-state: debt and balance for poolCaller as observable via public getters
        uint preDebt = c.getmapAddress_LPDebt(poolCaller);
        uint preBalance = c.getmapAddress_LPBalance(poolCaller);

        // attempt the call: since mintSynth is external and restricted by onlyPool modifier, it may revert
        bool reverted = false;
        try c.mintSynth{value:0}(member, amount) {
            // If this contract (InvMutTest) calls directly, msg.sender inside c is this contract, not poolCaller.
            // The check in c uses msg.sender; thus typically this call will revert unless this contract is a curated pool.
            // We just detect whether call succeeded.
        } catch {
            reverted = true;
        }

        uint postDebt = c.getmapAddress_LPDebt(poolCaller);
        uint postBalance = c.getmapAddress_LPBalance(poolCaller);
        uint memberBal = c.balanceOf(member);

        // General rule: If the external call did NOT revert, then postDebt == preDebt + amount and member's balance increased by amount.
        // If it reverted, none of the observed pool mappings for poolCaller changed (defensive: they remain equal to pre-state).
        assert((!reverted && postDebt == preDebt + amount && memberBal >= amount) || (reverted && postDebt == preDebt && postBalance == preBalance));
    }

    receive() external payable {}
}

