contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address pool, address member, uint amount) public payable {
        // precondition: pool must be a curated pool according to the DAO POOLFACTORY
        // We cannot call internal DAO directly here before using c, but we can require amount>0 to avoid trivial zero-mint cases
        require(amount > 0, "amount>0");

        // Observe state before the mint
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);

        bool reverted = false;
        // Call mintSynth on c as if from pool: but the test contract is the caller. To simulate call from pool, we rely on the fact
        // the minted function has onlyPool modifier which checks msg.sender is a curated pool. Since this test contract is not that pool,
        // the call will typically revert. For the property we check the case when it does NOT revert.
        try c.mintSynth(member, amount) returns (uint minted) {
            // success
            reverted = false;
            // After successful call, read after-state values
            uint afterTotal = c.totalSupply();
            uint afterDebt = c.getmapAddress_LPDebt(address(this));

            // The single assert must be at the end; we encode the property as follows:
            // If the call succeeded and the pool (msg.sender inside mintSynth) is this contract, then totalSupply increased by minted
