    // We cannot call c.mintSynth as if msg.sender == pool directly because msg.sender will be this test contract.
    // However the spec requires that only calls where msg.sender is a curated pool succeed; we check both cases by calling
    // via low-level call using the pool as caller through a simple approach: we simulate the pool by performing a direct call
    // from this contract to c.mintSynth and then we observe effects. The property we assert is conditional: if the call did not revert
    // and returned successfully, then totalSupply increased by 'amount' and the pool-specific debt/balance changed appropriately.

    // Note: We must make the state-changing call at top-level; therefore we perform a low-level call to c with abi-encoded selector.

    function run(address pool, address member, uint256 amount) public payable {
        require(member != address(0));
        // Read pre-state via public getters
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);
        uint256 beforeLPBal = c.getmapAddress_LPBalance(pool);

