        (success, ret) = address(c).call(payload);

        // Read post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterDebt = c.getmapAddress_LPDebt(pool);
        uint256 afterLPBal = c.getmapAddress_LPBalance(pool);

        // If the call succeeded, then:
        // - totalSupply increased by exactly 'amount'
        // - mapSynth_LPDebt[pool] increased by exactly 'amount'
        // - mapSynth_LPBalance[pool] increased by some non-negative amount (the minted LP units), and the increase equals afterLPBal - beforeLPBal
        // We cannot observe the exact LP units expected except via the public getter difference, so we assert consistency.
        // Formally: success => (afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount && afterLPBal >= beforeLPBal)

        assert(!success || (afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount && afterLPBal >= beforeLPBal));
    }

    receive() external payable {}
}

