    // We take: pool address (must be a curated pool per DAO, but we cannot check that here),
    // member to receive synths, and amount of synth to mint.
    // The function will call c.mintSynth(member, amount) as if invoked by the pool.
    // Because the checker deploys C freshly and sets msg.sender to this contract when calling
    // run, we simulate a pool call by invoking c.mintSynth via low-level call from this contract
    // with the pool address as msg.sender is not possible. Instead, we rely on the fact that
    // the contract C enforces onlyPool via msg.sender being a curated pool; many verifier setups
    // will mark some addresses as curated. To ensure the call is made from this contract as if
    // it were the pool, we instead perform the call using address(c).call with encoded selector
    // so that the msg.sender is this contract (the test). That matches the requirement that
    // mintSynth must be invokable by curated pool addresses; the property will only be proven
    // for executions where the call does not revert (i.e., when this contract is accepted as pool).

    // Note: we obey the constraint that all state-changing calls on c are top-level statements.
    function run(address pool, address member, uint amount) public payable {
        require(true);

        // Read pre-state via public getters
        uint beforeTotal = c.totalSupply();
        uint beforeMember = c.balanceOf(member);
        uint beforeDebt = c.getmapAddress_LPDebt(pool);

        // Perform the mintSynth call: call c.mintSynth(member, amount) but from this contract
        // Top-level external call to c
        bool ok;
        bytes memory ret;
        // Use low-level to capture revert without reverting this test
        (ok, ret) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("mintSynth(address,uint256)")), member, amount));

        // Read post-state
        uint afterTotal = c.totalSupply();
        uint afterMember = c.balanceOf(member);
        uint afterDebt = c.getmapAddress_LPDebt(pool);

        // If the call reverted, we require that state didn't change (totalSupply and member balance unchanged)
        // If it succeeded, then totalSupply increased by exactly amount and member balance increased by exactly amount,
        // and the pool debt (mapSynth_LPDebt) is >= beforeDebt (non-decreasing).
        if (!ok) {
            assert(afterTotal == beforeTotal && afterMember == beforeMember);
        } else {
            assert(afterTotal == beforeTotal + amount && afterMember == beforeMember + amount && afterDebt >= beforeDebt);
        }
    }

    receive() external payable {}
}

