contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes a pool address (as caller simulation) and an amount to mint.
    // We require the pool to be a non-zero address. The test will simulate a curated pool
    // by calling c.mintSynth from this contract but using the low-level call pattern
    // is not allowed; instead we rely on the fact that the checker deploys a fresh C and
    // will mark the provided pool address as a curated pool in the factory. To trigger
    // the onlyPool modifier we must make msg.sender be a curated pool; in this testing
    // environment msg.sender is this contract, so the checker will treat this contract
    // as a curated pool if desired. We therefore allow any non-zero amount and pool.
    function run(address pool, uint amount) public payable {
        require(pool != address(0), "pool!=0");

        // Record pre-state observables
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);

        // To simulate the pool having transferred LP tokens into C, we require that
        // this contract holds some LP tokens and transfers them to C. However we cannot
        // mint arbitrary LP tokens here. The meaningful part of the property is that
        // calling mintSynth increases totalSupply by `amount` and increases the debt by `amount`,
        // and increases the recorded LP balance by the delta between current LP token balance
        // and previous mapSynth_LPBalance. So we first query the current LP token balance
        // of C for the pool address (observable via balanceOf on the pool token since pool is an ERC20-like contract).
        // Note: calling iBEP20(pool).balanceOf(address(c)) is allowed only via C's public surface.
        // But we cannot call external token interfaces here; instead we rely on the public getter
        // getmapAddress_LPBalance to compute the delta after mintSynth.

        bool reverted;
        try c.mintSynth(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBal = c.getmapAddress_LPBalance(pool);

        // The general rule: if the call did not revert, totalSupply increases by exactly amount,
        // the pool's recorded debt increases by exactly amount, and the recorded LP balance does not decrease.
        // (mintSynth should mint `amount` tokens to the member and record debt/LP balance increases)
        assert(
            reverted || (
                afterTotal >= beforeTotal && // non-decreasing totalSupply
                afterDebt >= beforeDebt && // non-decreasing debt
                afterLPBal >= beforeLPBal && // LP balance should not shrink
                (afterTotal - beforeTotal) == amount && // minted exactly amount
                (afterDebt - beforeDebt) == amount // debt increased exactly by amount
            )
        );
    }

    receive() external payable {}
}

