        // and the decreases in mapSynth_LPBalance and mapSynth_LPDebt are not negative. This captures that burning cannot increase these metrics.
        assert(
            reverted
            ? (
                afterTotal == beforeTotal
                && afterBalanceContract == beforeBalanceContract
                && afterMapLPBalance == beforeMapLPBalance
                && afterMapLPDebt == beforeMapLPDebt
              )
            : (
                // successful return: values did not increase
                afterTotal <= beforeTotal
                && afterBalanceContract <= beforeBalanceContract
                && afterMapLPBalance <= beforeMapLPBalance
                && afterMapLPDebt <= beforeMapLPDebt
              )
        );
    }

    receive() external payable { }
}

