contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising burnSynth: msg.sender will be this contract when calling c.
    // We assert that either burnSynth reverts, or mapSynth_LPDebt[msg.sender] decreases by the burned synthetic amount
    // and c's balanceOf(address(this)) decreases by that same synthetic amount.
    function run() public payable {
        // record pre-state
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));
        uint beforeSynthBal = c.balanceOf(address(this));

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDebt = c.getmapAddress_LPDebt(address(this));
        uint afterSynthBal = c.balanceOf(address(this));

        // derive observed burned synthetic amount when call did not revert
        // burned = beforeSynthBal - afterSynthBal (non-negative)
        // The rule: if not reverted then afterDebt == beforeDebt - burned AND afterSynthBal == beforeSynthBal - burned
        // To avoid underflow in assert we check the <= relations before subtraction.
        bool ok;
        if (reverted) {
            ok = true;
        } else {
            // require that beforeSynthBal >= afterSynthBal and beforeDebt >= afterDebt
            if (beforeSynthBal >= afterSynthBal && beforeDebt >= afterDebt) {
                uint burned = beforeSynthBal - afterSynthBal;
                // burned should equal the decrease in recorded debt
                ok = (beforeDebt - afterDebt) == burned;
            } else {
                ok = false;
            }
        }

        assert(ok);
    }

    // accept ETH if needed by c calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising burnSynth: msg.sender will be this contract when calling c.
    // We assert that either burnSynth reverts, or the decreases in mapSynth_LPDebt and mapSynth_LPBalance
    // correspond to the synthetic amount burned and LP units redeemed as performed by burnSynth.
    function run() public payable {
        // record pre-state observable through public interface
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));
        uint beforeLPBal = c.getmapAddress_LPBalance(address(this));
        uint beforeSynthBal = c.balanceOf(address(this));

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDebt = c.getmapAddress_LPDebt(address(this));
        uint afterLPBal = c.getmapAddress_LPBalance(address(this));
        uint afterSynthBal = c.balanceOf(address(this));

        // If call reverted we accept it. Otherwise derive burned synthetic amount and LP units redeemed
        // burnedSynth = beforeSynthBal - afterSynthBal
        // debtDecrease = beforeDebt - afterDebt
        // lpDecrease = beforeLPBal - afterLPBal
        // The contract's code intends debtDecrease == burnedSynth and lpDecrease == (burnedSynth * beforeLPBal) / beforeDebt
        // To avoid invalid arithmetic we only assert the relation when preconditions hold.

        bool ok;
        if (reverted) {
            ok = true;
        } else {
            // require monotonic decreases (no unexpected increases)
            if (beforeSynthBal >= afterSynthBal && beforeDebt >= afterDebt && beforeLPBal >= afterLPBal) {
                uint burnedSynth = beforeSynthBal - afterSynthBal;
                uint debtDecrease = beforeDebt - afterDebt;
                uint lpDecrease = beforeLPBal - afterLPBal;

                // If beforeDebt is zero then the function's division would have been invalid; ensure consistency:
                if (beforeDebt == 0) {
                    // when no recorded debt there should be no burned synthetic and no lp decrease
                    ok = (burnedSynth == 0 && debtDecrease == 0 && lpDecrease == 0);
                } else {
                    // expected lpDecrease = (burnedSynth * beforeLPBal) / beforeDebt
                    uint expectedLPDecrease = (burnedSynth * beforeLPBal) / beforeDebt;
                    ok = (debtDecrease == burnedSynth) && (lpDecrease == expectedLPDecrease);
                }
            } else {
                ok = false;
            }
        }

        assert(ok);
    }

    receive() external payable {}
}

