    // Single public entry exercising burnSynth: msg.sender will be this contract when calling c.
    // We assert that either burnSynth reverts, or the observed public state changes match C.burnSynth's specification.
    function run() public payable {
        // Observe pre-state via public getters
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));
        uint beforeLPBal = c.getmapAddress_LPBalance(address(this));
