        uint afterLPBal = c.getmapAddress_LPBalance(address(this));
        uint afterSynthBal = c.balanceOf(address(this));

        // Exactly one assert as required. The asserted property:
        // If the call reverted, accept. Otherwise:
        //  - debt decreases by burnedSynth = beforeSynthBal - afterSynthBal
        //  - LP balance decreases (or stays) by lpDecrease = beforeLPBal - afterLPBal
        //  - If beforeDebt == 0 then nothing should change (no burn possible): burnedSynth==0, debt unchanged, lp unchanged
        //  - If beforeDebt > 0 then debtDecrease == burnedSynth and lpDecrease == (burnedSynth * beforeLPBal) / beforeDebt
        bool ok;
        if (reverted) {
