            if (afterDebt <= beforeDebt && afterLPBal <= beforeLPBal && afterSynthBal <= beforeSynthBal) {
                uint burnedSynth = beforeSynthBal - afterSynthBal;
                uint debtDecrease = beforeDebt - afterDebt;
                uint lpDecrease = beforeLPBal - afterLPBal;

                if (beforeDebt == 0) {
                    ok = (burnedSynth == 0) && (debtDecrease == 0) && (lpDecrease == 0);
                } else {
