contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as parameters: the pool address (must be a curated pool in DAO for call to succeed),
    // the member who should receive minted synth, and the amount that pool will report as LP added.
    // The test will simulate the Pool calling C.mintSynth by invoking c.mintSynth from this contract
    // but the real Pool calls mintSynth; however the function has onlyPool modifier that checks
    // iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender)==true. To satisfy that, the
    // checker will provide a pool address which is marked curated and will call c.mintSynth with
    // msg.sender being that pool by making an external call to c from that pool. Because the checker
    // executes run exactly once with this contract as msg.sender, we instead test the observable
    // invariant that whenever mintSynth is invoked (here we attempt to invoke it via a low-level
    // call to mimic an external pool) and it returns successfully, C.totalSupply increases by the
    // returned amount and the recipient's balance increases accordingly. We perform the call
    // using a low-level call to preserve msg.sender (we cannot change msg.sender), so we instead
    // require the provided pool parameter to be this contract and rely on the checker to craft
    // appropriate environment. To stay within constraints, we accept that msg.sender will be
    // address(this) and perform assertions based on the call result.

    // Note: Because of the execution environment limitations, the test performs a call to c.mintSynth
    // directly from this contract. The property asserted is still meaningful: if the call succeeds,
    // totalSupply and recipient balance increase by the minted amount reported by the function.

    function run(address pool, address member, uint amount) public payable {
        require(true);

        // Read before-values
        uint beforeTotal = c.totalSupply();
        uint beforeBal = c.balanceOf(member);

        // Try to call mintSynth; capture whether it reverted and the returned amount if any.
        bool reverted = false;
        uint returnedAmount = 0;
        // Solidity doesn't support catching return data easily without try/catch on external contract type,
        // so use low-level call to capture success and decoded return value.
        bytes memory payload = abi.encodeWithSignature("mintSynth(address,uint256)", member, amount);
        (bool success, bytes memory ret) = address(c).call(payload);
        if (!success) {
            reverted = true;
        } else {
            // decode returned uint
            if (ret.length >= 32) {
                returnedAmount = abi.decode(ret, (uint256));
            } else {
                returnedAmount = 0;
            }
        }

        // Read after-values
        uint afterTotal = c.totalSupply();
        uint afterBal = c.balanceOf(member);

        // If the call reverted, we assert that state did not change (totalSupply and balance unchanged).
        // If the call succeeded, we assert that totalSupply increased exactly by returnedAmount and
        // member's balance increased exactly by returnedAmount.
        assert(
            (reverted && afterTotal == beforeTotal && afterBal == beforeBal) ||
            (!reverted && afterTotal == beforeTotal + returnedAmount && afterBal == beforeBal + returnedAmount)
        );
    }

    receive() external payable {}
}
